import { useEffect, useState } from "react";
import "./Dashboard.css";

function Dashboard() {

 const [usuario,setUsuario] = useState("");
 const [compras,setCompras] = useState(0);
 const [gasto,setGasto] = useState(0);

 useEffect(()=>{

  const data = JSON.parse(localStorage.getItem("usuario"));

  if(data){

   setUsuario(data.nombre || data.usuario);

   // datos de ejemplo por ahora
   setCompras(data.compras || 2);
   setGasto(data.gasto || 37000);

  }

 },[]);

 return(

  <div className="dashboard">

   {/* HEADER */}

   <div className="header">

    <h1>Bienvenido, {usuario}</h1>
    <p>Panel de Control - Usuarios</p>

   </div>


   {/* ESTADISTICAS */}

   <div className="stats">

    <div className="card">

     <h2>{compras}</h2>
     <p>Compras Realizadas</p>

    </div>

    <div className="card">

     <h2>${gasto.toLocaleString()}</h2>
     <p>Gasto Total</p>

    </div>

   </div>


   {/* CATALOGO */}

   <h3 className="section">Catálogo y Compras</h3>

   <div className="menu">

    <div className="menu-item">

     <span>💎</span>

     <div>
      <h4>Comprar Esmeraldas</h4>
      <p>Explora nuestro catálogo premium</p>
     </div>

    </div>

    <div className="menu-item">

     <span>📋</span>

     <div>
      <h4>Historial de Compras</h4>
      <p>Revisa tus pedidos anteriores</p>
     </div>

    </div>

   </div>


   {/* CUENTA */}

   <h3 className="section">Mi Cuenta</h3>

   <div className="menu">

    <div className="menu-item">

     <span>👤</span>

     <div>
      <h4>Editar Perfil</h4>
     </div>

    </div>

   </div>

  </div>

 );

}

export default Dashboard;
